let currentLang = 'en';

function T(key) {
  return (LANG[currentLang] && LANG[currentLang][key]) || LANG.en[key] || key;
}

function applyTranslations(lang) {
  const source = LANG[lang] || LANG.en;
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    const val = source[key] || LANG.en[key];
    if (val) el.innerHTML = val;
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    const val = source[key] || LANG.en[key];
    if (val) el.placeholder = val;
  });
  document.getElementById('html-root').lang = lang;
}

function setLang(lang) {
  currentLang = lang;
  document.querySelectorAll('.lang-tog button').forEach(b => {
    b.classList.toggle('active',
      (lang === 'en' && b.textContent.includes('EN')) ||
      (lang === 'es' && b.textContent.includes('ES'))
    );
  });
  applyTranslations(lang);
  toast(lang === 'es' ? 'Idioma cambiado a espa&#xF1;ol' : ' Switched to English');
}

function checkMissingTranslations() {
  if (!window.console || !LANG || !LANG.en || !LANG.es) return;
  const keys = new Set();
  document.querySelectorAll('[data-i18n],[data-i18n-placeholder]').forEach(el => keys.add(el.getAttribute('data-i18n') || el.getAttribute('data-i18n-placeholder')));
  const missing = [...keys].filter(key => key && (!LANG.en[key] || !LANG.es[key]));
  if (missing.length) console.warn('HolisticVox missing translation keys:', missing);
}

document.addEventListener('DOMContentLoaded', function() {
  applyTranslations(currentLang);
  checkMissingTranslations();
});
